	Under the assumptions $(\mathbf{A_1})$,  $(\mathbf{A_2})$-$(\mathrm{i})$,  $(\mathbf{A_3})$ and $(\mathbf{A_4})$, we have a list of existence and estimation conclusions based on varying values of $\alpha$:
	\begin{enumerate}[(i)]
		\item If $\alpha\in (-b,+\infty)$, then the problem \eqref{equation}-\eqref{bcondition} admits a viscosity solution $u(x)\in C(\overline{\Omega})$, and there exists some constant $\overline{C_0}>0$ such that 
		\begin{equation*}
			u(x)\geq \psi(x)-\overline{C_0}\,d(x), \ \ \forall x\in\overline{\Omega}.
		\end{equation*}

\item If $\alpha=-b$, then the problem \eqref{equation}-\eqref{bcondition} admits a viscosity solution $u(x)\in C(\overline{\Omega})$, and there exists some constants $\overline{C_0},\,\overline{C_1}>0$ such that 
\begin{equation*}
u(x)\geq \psi(x)-\overline{C_0}\,d(x)\left(-\log\left(\overline{C_1}\,d(x)\right)\right)^{\frac{b}{a+b}}, \ \ \forall x\in\overline{\Omega}.
\end{equation*}

\item If $\alpha\in(-a-2b,-b)$, then the problem \eqref{equation}-\eqref{bcondition} admits a viscosity solution $u(x)\in C(\overline{\Omega})$, and there exists some constant $\overline{C_0}>0$ such that 
\begin{equation*}
	u(x)\geq \psi(x)-\overline{C_0}\left(d(x)\right)^{\frac{a+2b+\alpha}{a+b}}, \ \ \forall x\in\overline{\Omega}.
\end{equation*}
	\end{enumerate}

