			\item for $a = 1$, the explicit steady state $\omega_{1} = -\sin (x)$ solves the system with $c_{\omega,a} = 0$;
			\item for $1-\delta_{1}<a<1$, one has $c_{\omega,a} > 0$, and the solution $\omega(x,t)$ exists globally with $O(t^{-1})$ decay rate as $t\to\infty$.
		\end{itemize}

